{
  "name": "@yoloship/ai",
  "type": "module",
  "version": "0.1.0",
  "private": false,
  "description": "Yoloship AI — runtime-agnostic coding-agent orchestration layer (consumes @yoloship/claude-sdk today, opencode next)",
  "author": "Yoloship Team <team@yoloship.dev>",
  "license": "MIT",
  "homepage": "https://www.yoloship.dev",
  "keywords": [
    "yoloship",
    "ai",
    "runtime",
    "claude",
    "opencode",
    "agent"
  ],
  "sideEffects": false,
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.mjs"
    }
  },
  "main": "./dist/index.mjs",
  "types": "./dist/index.d.ts",
  "files": [
    "LICENSE",
    "dist"
  ],
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "zod": "^4.4.3",
    "@yoloship/claude-sdk": "0.1.0"
  },
  "devDependencies": {
    "@vitest/coverage-v8": "^4.1.4",
    "cross-env": "^10.1.0",
    "javascript-obfuscator": "^5.4.1",
    "typescript": "^5.9.3",
    "unbuild": "^3.5.0",
    "vitest": "^4.1.4"
  },
  "lint-staged": {
    "*.{js,ts,vue,mjs,mts,cjs,md,yml,json}": "cross-env NODE_ENV=production eslint --fix"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "unbuild && node scripts/obfuscate.mjs",
    "build:dev": "unbuild",
    "typecheck": "tsc --noEmit",
    "lint": "cross-env NODE_ENV=production eslint",
    "lint:fix": "cross-env NODE_ENV=production eslint --fix",
    "test:unit": "vitest run",
    "test:unit:watch": "vitest watch",
    "test:unit:coverage": "vitest run --coverage"
  }
}
